using Microsoft.AspNetCore.Antiforgery;using Microsoft.AspNetCore.Authentication;using SalekhPos.Subscriptions.Application.Subscriptions;using SalekhPos.Subscriptions.Contracts.Subscriptions;namespace SalekhPos.Api.Authentication;public static class WebSubscriptionEndpoints{public static void MapWebSubscriptionEndpoints(this WebApplication app){var g=app.MapGroup("/bff/api/v1").AllowAnonymous().RequireRateLimiting("business");g.MapGet("/organizations/{organizationId:guid}/subscriptions/plans",Plans);g.MapPost("/organizations/{organizationId:guid}/subscriptions/",Create);g.MapGet("/organizations/{organizationId:guid}/subscriptions/{subscriptionId:guid}",Get);g.MapPut("/organizations/{organizationId:guid}/subscriptions/{subscriptionId:guid}/plan",Plan);g.MapPost("/organizations/{organizationId:guid}/subscriptions/{subscriptionId:guid}/cancellation",Cancel);g.MapPost("/organizations/{organizationId:guid}/subscriptions/{subscriptionId:guid}/renewals",Renew);g.MapGet("/organizations/{organizationId:guid}/subscriptions/{subscriptionId:guid}/entitlements",Entitlements);}private static async Task<IResult> Plans(Guid organizationId,HttpContext c,WebAuthenticationState s,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);return i is null?Unauth(s):Results.Ok(await svc.ListPlansAsync(i,organizationId,ct));}private static async Task<IResult> Create(Guid organizationId,CreateSubscriptionRequest r,HttpContext c,WebAuthenticationState s,IAntiforgery a,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);if(i is null)return Unauth(s);if(!await WebAuthentication.ValidateMutation(c,a,s.Settings!))return Invalid();return Results.Ok(await svc.CreateAsync(i,organizationId,r,ct));}private static async Task<IResult> Get(Guid organizationId,Guid subscriptionId,HttpContext c,WebAuthenticationState s,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);return i is null?Unauth(s):Results.Ok(await svc.GetAsync(i,organizationId,subscriptionId,ct));}private static async Task<IResult> Plan(Guid organizationId,Guid subscriptionId,ChangePlanRequest r,HttpContext c,WebAuthenticationState s,IAntiforgery a,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);if(i is null)return Unauth(s);if(!await WebAuthentication.ValidateMutation(c,a,s.Settings!))return Invalid();return Results.Ok(await svc.ChangePlanAsync(i,organizationId,subscriptionId,r,ct));}private static async Task<IResult> Cancel(Guid organizationId,Guid subscriptionId,CancelSubscriptionRequest r,HttpContext c,WebAuthenticationState s,IAntiforgery a,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);if(i is null)return Unauth(s);if(!await WebAuthentication.ValidateMutation(c,a,s.Settings!))return Invalid();return Results.Ok(await svc.CancelAsync(i,organizationId,subscriptionId,r,ct));}private static async Task<IResult> Renew(Guid organizationId,Guid subscriptionId,RenewSubscriptionRequest r,HttpContext c,WebAuthenticationState s,IAntiforgery a,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);if(i is null)return Unauth(s);if(!await WebAuthentication.ValidateMutation(c,a,s.Settings!))return Invalid();return Results.Ok(await svc.RenewAsync(i,organizationId,subscriptionId,r,ct));}private static async Task<IResult> Entitlements(Guid organizationId,Guid subscriptionId,HttpContext c,WebAuthenticationState s,ISubscriptionService svc,CancellationToken ct){var i=await Id(c,s);return i is null?Unauth(s):Results.Ok(await svc.GetEntitlementsAsync(i,organizationId,subscriptionId,ct));}private static async Task<SubscriptionIdentity?> Id(HttpContext c,WebAuthenticationState s){if(s.Settings is null)return null;var r=await c.AuthenticateAsync(WebAuthentication.CookieScheme);if(!r.Succeeded||r.Principal is null)return null;var iss=r.Principal.FindAll("iss").ToArray();var sub=r.Principal.FindAll("sub").ToArray();if(iss.Length!=1||sub.Length!=1)return null;try{var i=new SubscriptionIdentity(iss[0].Value,sub[0].Value);i.Validate();return i;}catch(ArgumentException){return null;}}private static IResult Unauth(WebAuthenticationState s)=>s.Settings is null?Results.Problem(statusCode:503,title:"Web authentication is unavailable",extensions:new Dictionary<string,object?>{{"code","web_authentication_unavailable"}}):Results.Unauthorized();private static IResult Invalid()=>Results.Problem(statusCode:400,title:"The subscription request is invalid",extensions:new Dictionary<string,object?>{{"code","invalid_subscription_request"}});}